questionvariables.text:
/* --- 1. RESEARCH GOALS (goal -> most appropriate method) --- */
/* Methods restricted to those taught in the lesson.                       */
/* Scenarios deliberately different from the 'Identifying' question.       */
scenarios: [
  ["A school counsellor wants to understand, in depth, how a few students coped with exam stress and to explore their personal feelings about it.", "Interview"],
  ["A county government wants to quickly collect the ages and occupations of 5,000 residents using one standard form.", "Questionnaire"],
  ["A road-safety officer wants to find out how many drivers actually stop at a particular junction, watching them without their knowledge.", "Observation"],
  ["A science teacher wants to find out whether adding sugar to water makes beans germinate faster, keeping all other conditions equal.", "Experimentation"],
  ["A student writing a geography report needs rainfall figures for their region going back thirty years.", "Secondary Data Collection"]
];

/* Pick a random goal */
rand_idx: rand(length(scenarios)) + 1;
chosen_scenario: scenarios[rand_idx];
q_text: chosen_scenario[1];
correct_text: chosen_scenario[2];

/* --- 2. OPTIONS: correct + 3 distinct distractors from taught methods --- */
all_methods: ["Observation", "Interview", "Questionnaire", "Experimentation", "Secondary Data Collection"];
wrong_pool: sublist(all_methods, lambda([x], x # correct_text));
chosen_wrongs: rand_selection(wrong_pool, 3);

correct_answer: [[1, true, correct_text]];
incorrect_answers: [
   [2, false, chosen_wrongs[1]],
   [3, false, chosen_wrongs[2]],
   [4, false, chosen_wrongs[3]]
];
ta: random_permutation(append(correct_answer, incorrect_answers));

/* Helper for question testing: a wrong option's value */
wrongval(t) := first(delete(1, map(first, t)));
